#!/usr/bin/env node
/**
 * Development data for the local database (never production).
 *
 * Creates two merchants through the real POS API so stock, inventory movements,
 * shifts and accounting are generated by the same code the POS uses, then
 * backdates the sales and adds the Syncro Shop data (gallery, store profile,
 * publication) with SQL on the local Docker container.
 *
 * Usage: node scripts/seed-dev.mjs
 */
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { randomUUID } from 'node:crypto';

const API = 'http://localhost:9100';
const PASSWORD = 'Syncro2026!';
const DB_CONTAINER = 'syncro-dev-db';

// ── Safety: only ever run against the local database ────────────────────────
const envFile = readFileSync(new URL('../.env', import.meta.url), 'utf8');
const dbUrl = envFile.split('\n').find((l) => l.startsWith('DATABASE_URL='))?.slice('DATABASE_URL='.length) ?? '';
if (!/@localhost:5434\/syncro_dev/.test(dbUrl)) {
  console.error('❌ El backend no apunta a la base local (localhost:5434/syncro_dev). Abortando.');
  process.exit(1);
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const rand = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

// The API allows 60 requests per minute.
async function api(method, path, body, token) {
  for (let attempt = 0; attempt < 5; attempt++) {
    await sleep(1050);
    const res = await fetch(API + path, {
      method,
      headers: {
        'Content-Type': 'application/json',
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
      },
      body: body ? JSON.stringify(body) : undefined,
    });
    if (res.status === 429) {
      console.log('   …límite de peticiones, esperando 60 s');
      await sleep(60000);
      continue;
    }
    const text = await res.text();
    const data = text ? JSON.parse(text) : null;
    if (!res.ok) throw new Error(`${method} ${path} → ${res.status}: ${text.slice(0, 300)}`);
    return data;
  }
  throw new Error(`${method} ${path}: demasiados reintentos`);
}

function sql(query) {
  return execFileSync('docker', ['exec', '-i', DB_CONTAINER, 'psql', '-U', 'postgres', '-d', 'syncro_dev', '-v', 'ON_ERROR_STOP=1', '-Atq'], {
    input: query,
  }).toString().trim();
}
const q = (v) => (v === null || v === undefined ? 'NULL' : `'${String(v).replace(/'/g, "''")}'`);

async function dummyImages(id) {
  const res = await fetch(`https://dummyjson.com/products/${id}?select=images,thumbnail`);
  const data = await res.json();
  return data.images?.length ? data.images : [data.thumbnail];
}

