const PAYMENTS = ['CASH', 'CASH', 'CARD', 'PAGO_MOVIL', 'PAGO_MOVIL', 'TRANSFER', 'BINANCE'];

async function seedMerchant(m) {
  console.log(`\n🏪 ${m.businessName}`);
  await api('POST', '/auth/register', { ...m.owner, password: PASSWORD, businessName: m.businessName });
  const { access_token: token } = await api('POST', '/auth/login', { email: m.owner.email, password: PASSWORD });
  const branches = await api('GET', '/branches', null, token);
  const main = branches.find((b) => b.isMain) ?? branches[0];
  const businessId = main.businessId;
  console.log('   ✓ negocio, dueño y sucursal principal');

  await api('PUT', '/settings', { isSyncroVendor: true, businessPhone: m.whatsapp, businessAddress: m.address }, token);

  let second = null;
  if (m.secondBranch) {
    second = await api('POST', '/branches', { name: m.secondBranch, location: m.owner.city, country: 'Venezuela' }, token);
    console.log(`   ✓ segunda sucursal: ${m.secondBranch}`);
  }

  const categoryIds = {};
  for (const name of m.categories) {
    categoryIds[name] = (await api('POST', '/categories', { name }, token)).id;
  }
  console.log(`   ✓ ${m.categories.length} categorías`);

  const created = [];
  for (const [i, p] of m.products.entries()) {
    const images = await dummyImages(p.dj);
    const product = await api('POST', '/products', {
      name: p.name,
      description: p.desc,
      categoryId: categoryIds[p.cat],
      isWeighable: Boolean(p.weighable),
      image: images[0],
      variants: p.variants.map(([name, price, cost, stock], vi) => ({
        name, price, cost, stock, minStock: 5,
        sku: `${m.slug.slice(0, 3).toUpperCase()}-${String(i + 1).padStart(3, '0')}-${vi + 1}`,
        branchId: main.id,
      })),
    }, token);
    created.push({ ...p, id: product.id, images, variants: product.variants });
  }
  console.log(`   ✓ ${created.length} productos con inventario`);

  const clientIds = [];
  for (const [name, phone] of m.clients) {
    clientIds.push((await api('POST', '/clients', { name, phone }, token)).id);
  }
  console.log(`   ✓ ${clientIds.length} clientes`);

  await api('POST', '/shifts/open', { openingBalance: 50, branchId: main.id }, token);
  const remaining = new Map(created.flatMap((p) => p.variants.map((v) => [v.id, v.stock])));
  const priceOf = new Map(created.flatMap((p) => p.variants.map((v) => [v.id, v.price])));
  const weighable = new Set(created.filter((p) => p.weighable).flatMap((p) => p.variants.map((v) => v.id)));
  let salesCount = 0;
  for (let s = 0; s < m.sales; s++) {
    const items = [];
    for (let k = 0; k < rand(1, 4); k++) {
      const candidates = [...remaining].filter(([id, st]) => st >= 2 && !items.some((it) => it.variantId === id));
      if (!candidates.length) break;
      const [variantId, stock] = pick(candidates);
      const quantity = weighable.has(variantId) ? Math.round(rand(5, 25) / 10 * 10) / 10 : Math.min(rand(1, 3), Math.floor(stock / 2));
      if (quantity <= 0) continue;
      items.push({ variantId, quantity });
      remaining.set(variantId, stock - quantity);
    }
    if (!items.length) break;
    const subtotal = items.reduce((sum, it) => sum + priceOf.get(it.variantId) * it.quantity, 0);
    const method = pick(PAYMENTS);
    const total = Math.round(subtotal * 1.16 * (method === 'CASH' ? 1.03 : 1) * 100) / 100;
    await api('POST', '/sales', {
      branchId: main.id,
      items,
      payments: [{ method, amount: total }],
      clientId: Math.random() < 0.45 ? pick(clientIds) : undefined,
    }, token);
    salesCount++;
  }
  console.log(`   ✓ ${salesCount} ventas`);

  // ── SQL part (local container only) ──────────────────────────────────────
  const statements = [];
  // Spread the sales over the last 45 days, during opening hours.
  // POS sales are stored without businessId; they belong to the business through the branch.
  statements.push(`
    UPDATE "Sale" s SET "createdAt" = date_trunc('day', now()) - (floor(random() * 45) || ' days')::interval + ((8 + floor(random() * 11)) || ' hours')::interval + (floor(random() * 60) || ' minutes')::interval
    FROM "Branch" br WHERE br."id" = s."branchId" AND br."businessId" = ${q(businessId)};
    UPDATE "AccountingEntry" a SET "createdAt" = s."createdAt" FROM "Sale" s JOIN "Branch" br ON br."id" = s."branchId" WHERE a."saleId" = s."id" AND br."businessId" = ${q(businessId)};
  `);
  // Second branch shares part of the catalog with its own stock
  if (second) {
    for (const p of created.slice(0, 12)) {
      for (const v of p.variants) {
        statements.push(`INSERT INTO "Inventory" ("id","variantId","branchId","quantity","createdAt","updatedAt") VALUES (${q(randomUUID())}, ${q(v.id)}, ${q(second.id)}, ${rand(5, 40)}, now(), now()) ON CONFLICT DO NOTHING;`);
      }
    }
  }
  // A realistic BCV rate so prices in bolívares can be tested
  statements.push(`UPDATE "Setting" SET "exchangeRate" = 195.42 WHERE "businessId" = ${q(businessId)};`);
  // Gallery (up to 5) and Syncro Shop publication from the main branch
  for (const [i, p] of created.entries()) {
    p.images.slice(0, 5).forEach((url, pos) => {
      statements.push(`INSERT INTO "ProductImage" ("id","productId","url","position") VALUES (${q(randomUUID())}, ${q(p.id)}, ${q(url)}, ${pos});`);
    });
    const published = i < Math.ceil(created.length * 0.85);
    statements.push(`UPDATE "Product" SET "isPublishedOnSyncroShop" = ${published}, "isFeaturedOnSyncroShop" = ${Boolean(p.featured && published)}, "syncroShopBranchId" = ${published ? q(main.id) : 'NULL'}, "specifications" = ${p.specs ? q(JSON.stringify(p.specs.map(([label, value]) => ({ label, value })))) + '::jsonb' : 'NULL'} WHERE "id" = ${q(p.id)};`);
  }
  statements.push(`
    INSERT INTO "StoreProfile" ("id","businessId","slug","displayName","description","address","latitude","longitude","phone","whatsapp","email","schedule","pickupEnabled","deliveryEnabled","deliveryCost","freeDeliveryFrom","minOrderAmount","deliveryTime","returnPolicy")
    VALUES (${q(randomUUID())}, ${q(businessId)}, ${q(m.slug)}, ${q(m.businessName)}, ${q(m.description)}, ${q(m.address)}, ${m.coords[0]}, ${m.coords[1]}, ${q(m.whatsapp)}, ${q(m.whatsapp)}, ${q(m.owner.email)},
      ${q(JSON.stringify({ lun: ['08:00', '19:00'], mar: ['08:00', '19:00'], mie: ['08:00', '19:00'], jue: ['08:00', '19:00'], vie: ['08:00', '19:00'], sab: ['08:00', '14:00'], dom: null }))}::jsonb,
      true, true, 2, 40, 5, 'Mismo día si pides antes de las 3 p. m.', 'Cambios dentro de los 7 días con factura y empaque original.')
    ON CONFLICT ("businessId") DO NOTHING;
  `);
  sql(statements.join('\n'));
  console.log('   ✓ ventas repartidas en 45 días, galería, publicación en Syncro Shop y perfil de tienda');
}

